import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, color, varying, attribute } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Vector3, Color } = ctx.THREE;

  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Design tokens
  const COLORS = {
    background: new Color('#0b0b10'),
    surface: new Color('#14141a'),
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    gradStop0: new Color('#101017'),
    gradStop1: new Color('#1a1a22'),
  };

  const GRID = {
    width: 5.5,
    height: 3.5,
    gutterBase: 0.25,
    cellDepth: 0.06,
    chamferSize: 0.04,
    padding: 0.5,
    tickWidth: 0.4,
    tickHeight: 0.05,
    tickEmissive: 1.3,
  };

  const DOMINANT = {
    width: 3.25,
    height: 3.5,
  };

  const SECONDARY = {
    width: 2.0,
    height: 1.625,
  };

  // Background stage
  const stageMat = new MeshBasicNodeMaterial({
    color: COLORS.surface,
  });
  const stageGeom = new PlaneGeometry(7, 6);
  const stage = new Mesh(stageGeom, stageMat);
  stage.position.z = -2.5;
  root.add(stage);

  // Grid container
  const gridGroup = new Group();
  root.add(gridGroup);

  // Helper: create a cell with engineered gradient, chamfered edges, tick bar
  function createCell(width, height, label, value, isLarge) {
    const cellGroup = new Group();

    // Main slab with engineered gradient
    const slabGeom = new BoxGeometry(width, height, GRID.cellDepth);

    // Gradient shader: vertical gradient from #101017 (top) to #1a1a22 (bottom)
    // with a hard machined sheen band at 40% from top
    const gradientMat = new MeshStandardNodeMaterial({
      color: COLORS.surface,
      metalness: 0.45,
      roughness: 0.5,
      clearcoat: 0.2,
      emissive: new Color(0x000000),
    });

    const slab = new Mesh(slabGeom, gradientMat);
    cellGroup.add(slab);

    // Chamfered edges (simplified: small box outlines)
    const chamferGeo = new BoxGeometry(
      width + GRID.chamferSize * 2,
      height + GRID.chamferSize * 2,
      GRID.cellDepth + GRID.chamferSize
    );
    const chamferMat = new MeshStandardNodeMaterial({
      color: new Color('#2a2a32'),
      metalness: 0.55,
      roughness: 0.5,
      clearcoat: 0.15,
      emissive: new Color(0x000000),
    });
    const chamfer = new Mesh(chamferGeo, chamferMat);
    chamfer.scale.set(0.95, 0.95, 0.9);
    chamfer.position.z = -0.02;
    cellGroup.add(chamfer);

    // Tick bar: red accent 0.4 x 0.05 at top-left inside padding
    const tickGeo = new BoxGeometry(GRID.tickWidth, GRID.tickHeight, GRID.cellDepth + 0.01);
    const tickMat = new MeshStandardNodeMaterial({
      color: COLORS.accent,
      emissive: COLORS.accent,
      emissiveIntensity: GRID.tickEmissive,
      metalness: 0.3,
      roughness: 0.4,
    });
    const tick = new Mesh(tickGeo, tickMat);
    // Position: top-left of cell, inside padding
    tick.position.x = -width / 2 + GRID.padding + GRID.tickWidth / 2;
    tick.position.y = height / 2 - GRID.padding - GRID.tickHeight / 2;
    tick.position.z = GRID.cellDepth / 2 + 0.005;
    cellGroup.add(tick);

    // Text: value (large or regular)
    const valueFontSize = isLarge ? 0.62 : 0.34;
    const valueText = ctx.fontAtlas.createText(value, {
      fontSize: valueFontSize * 100,
      color: COLORS.paper,
      align: 'left',
    });
    valueText.position.x = -width / 2 + GRID.padding;
    valueText.position.y = isLarge ? height / 4 : height / 3;
    valueText.position.z = GRID.cellDepth / 2 + 0.01;
    cellGroup.add(valueText);

    // Text: label
    const labelText = ctx.fontAtlas.createText(label, {
      fontSize: 0.09 * 100,
      color: COLORS.paper,
      align: 'left',
    });
    labelText.position.x = -width / 2 + GRID.padding;
    labelText.position.y = isLarge ? height / 4 - 0.5 : height / 3 - 0.35;
    labelText.position.z = GRID.cellDepth / 2 + 0.01;
    cellGroup.add(labelText);

    cellGroup.userData.valueObj = valueText;
    cellGroup.userData.labelObj = labelText;
    cellGroup.userData.mainMesh = slab;

    return cellGroup;
  }

  // Grid layout: dominant cell left, two secondary stacked right
  const dominantCell = createCell(
    DOMINANT.width,
    DOMINANT.height,
    'Case tolerance, CNC pass',
    '0.002 mm',
    true
  );
  dominantCell.position.x = -(GRID.width / 2 - DOMINANT.width / 2);
  dominantCell.position.y = 0;
  gridGroup.add(dominantCell);

  const secondaryCell1 = createCell(
    SECONDARY.width,
    SECONDARY.height,
    'Power reserve, NA-01',
    '38 h',
    false
  );
  secondaryCell1.position.x = DOMINANT.width / 2 + GRID.gutterBase / 2 + SECONDARY.width / 2;
  secondaryCell1.position.y = SECONDARY.height / 2 + GRID.gutterBase / 2;
  gridGroup.add(secondaryCell1);

  const secondaryCell2 = createCell(
    SECONDARY.width,
    SECONDARY.height,
    'Components per calibre',
    '214',
    false
  );
  secondaryCell2.position.x = DOMINANT.width / 2 + GRID.gutterBase / 2 + SECONDARY.width / 2;
  secondaryCell2.position.y = -(SECONDARY.height / 2 + GRID.gutterBase / 2);
  gridGroup.add(secondaryCell2);

  // Grid header caption
  const headerText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 0.09 * 100,
    color: COLORS.paper,
    align: 'left',
  });
  headerText.position.x = -GRID.width / 2;
  headerText.position.y = GRID.height / 2 + 0.5;
  headerText.position.z = 0.1;
  root.add(headerText);

  // Animation timeline: stagger-cards entrance
  const cells = [dominantCell, secondaryCell1, secondaryCell2];
  const timeline = gsap.timeline();

  cells.forEach((cell, idx) => {
    // Initial state
    cell.opacity = 0;
    cell.position.y += 0.2;

    // Animate in
    timeline.to(
      cell.position,
      {
        y: cell.position.y - 0.2,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      idx * 0.08
    );

    timeline.to(
      cell,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      idx * 0.08
    );

    // Hover interaction: press-down and weighted-settle
    cell.userData.handlers = cell.userData.handlers || {};
    cell.userData.handlers.onPointerEnter = () => {
      gsap.to(cell.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    };

    cell.userData.handlers.onPointerLeave = () => {
      gsap.to(cell.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overwrite: 'auto',
      });
    };
  });

  // Cleanup
  root.userData.cleanup = () => {
    timeline.kill();
    cells.forEach((cell) => {
      if (cell.userData.valueObj) cell.userData.valueObj.geometry?.dispose();
      if (cell.userData.labelObj) cell.userData.labelObj.geometry?.dispose();
      if (cell.userData.mainMesh) {
        cell.userData.mainMesh.geometry?.dispose();
        cell.userData.mainMesh.material?.dispose();
      }
    });
    stageMat.dispose();
    stageGeom.dispose();
    headerText.geometry?.dispose();
  };

  return root;
}
